SELECT * FROM (SELECT CASE WHEN budget >= 3165000 THEN 'high' WHEN budget >= 1100000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, MAX(budget) - MIN(budget) AS budget_range, COUNT(DISTINCT budget) AS unique_dept_names FROM departments GROUP BY CASE WHEN budget >= 3165000 THEN 'high' WHEN budget >= 1100000 THEN 'mid' ELSE 'low' END, location) AS agg WHERE unique_dept_names >= 7 ORDER BY location, budget_bucket LIMIT 10;
